\implies \abs{f(Rz+a)\over M}
&\leq \abs{z} \\
\implies \abs{f(Rz+a)} &\leq M\abs{z} \\
\implies \abs{f(w)} &\leq M\abs{w-a\over R} \qquad w = Rz+a\implies z={w-a\over R}
.\]
